class Solution {
public:
    long long minCuttingCost(int n, int m, int k) {
        long long L = max(n, m);
        if (L <= k) return 0;
        long long best = LLONG_MAX;
        for (long long p = L - k; p <= k; p++) best = min(best, p * (L - p));
        return best;
    }
};

