class Solution {
    public long minCuttingCost(int n, int m, int k) {
        long L = Math.max(n, m);
        if (L <= k) return 0;
        long best = Long.MAX_VALUE;
        for (long p = L - k; p <= k; p++) best = Math.min(best, p * (L - p));
        return best;
    }
}

